type Category = 'Stationery' | 'Printer' | 'Kitchen' | 'Cleaning' | 'Tech';
type Unit = 'each' | 'box' | 'ream' | 'pack';
type MovementReason = 'Issued' | 'Received' | 'Damaged' | 'Adjustment' | 'Stocktake';
type PurchaseRequestStatus = 'Open' | 'Approved' | 'Ordered' | 'Received' | 'Cancelled';

interface Item {
  id: string;
  name: string;
  category: Category;
  unit: Unit;
  currentQty: number;
  reorderLevel: number;
  targetQty: number;
  location: string;
  active: boolean;
  unitCostPence?: number;
}

interface Movement {
  id: string;
  item: string;
  delta: number;
  reason: MovementReason;
  actor: string;
  timestamp: string;
  note: string;
  resultingQty: number;
}

interface PurchaseRequest {
  id: string;
  item: string;
  requestedQty: number;
  status: PurchaseRequestStatus;
  raisedBy: string;
  decisionNote: string;
}

interface ListFilter {
  search?: string;
  category?: Category | '';
  needsReorderOnly?: boolean;
  sortKey?: 'name' | 'qty' | 'category';
  sortDir?: 'asc' | 'desc';
}

interface ItemRow {
  id: string;
  name: string;
  category: Category;
  unit: Unit;
  currentQty: number;
  reorderLevel: number;
  location: string;
  statusColour: string;
  statusText: string;
  needsReorder: boolean;
}

interface IssueResult {
  ok: boolean;
  error: string;
  movement: Movement | null;
  item: Item | null;
}

interface ReceiveResult {
  ok: boolean;
  error: string;
  movement: Movement | null;
  item: Item | null;
  request: PurchaseRequest | null;
}

interface InvariantMismatch {
  itemId: string;
  expected: number;
  stored: number;
}

interface InvariantReport {
  ok: boolean;
  mismatches: InvariantMismatch[];
}

interface State {
  items: Item[];
  movements: Movement[];
  purchaseRequests: PurchaseRequest[];
}

var state: State = { items: [], movements: [], purchaseRequests: [] };
var idCounter = 0;
var clockCounter = 0;

function nextId(): string {
  idCounter += 1;
  return 'id_' + idCounter.toString();
}

function nextTimestamp(): string {
  clockCounter += 1;
  var base = 1700000000000;
  var t = base + clockCounter * 1000;
  return new Date(t).toISOString();
}

function isNonNegativeInteger(v: unknown): boolean {
  if (typeof v !== 'number') return false;
  if (!isFinite(v)) return false;
  if (Math.floor(v) !== v) return false;
  if (v < 0) return false;
  return true;
}

function findItem(items: Item[], id: string): Item | null {
  var i = 0;
  for (i = 0; i < items.length; i += 1) {
    if (items[i].id === id) return items[i];
  }
  return null;
}

function addMovement(item: Item, delta: number, reason: MovementReason, actor: string, note: string): Movement {
  var resulting = item.currentQty + delta;
  var m: Movement = {
    id: nextId(),
    item: item.id,
    delta: delta,
    reason: reason,
    actor: actor,
    timestamp: nextTimestamp(),
    note: note,
    resultingQty: resulting
  };
  state.movements.push(m);
  item.currentQty = resulting;
  return m;
}

/**
 * Sets the working state used by every inventory operation. Deterministic; no IO.
 * @param items - the item records to persist
 * @param movements - the movement log
 * @param purchaseRequests - the purchase request records
 * @returns the state that is now active
 */
function persistState(items: Item[], movements: Movement[], purchaseRequests: PurchaseRequest[]): State {
  state = { items: items, movements: movements, purchaseRequests: purchaseRequests };
  return state;
}

/**
 * Lists items filtered by search/category/needs-reorder and sorts by name, qty or category.
 * Empty search returns all items; no matches returns an empty list without error.
 * @param items - the item records to list
 * @param filter - search text, category, needs-reorder toggle and sort key/direction
 * @returns the filtered, sorted rows with a colour-coded status
 */
function listItems(items: Item[], filter: ListFilter): ItemRow[] {
  var rows: ItemRow[] = [];
  var search = typeof filter.search === 'string' ? filter.search : '';
  var needle = search.trim().toLowerCase();
  var category = filter.category;
  var reorderOnly = filter.needsReorderOnly === true;
  var i = 0;
  for (i = 0; i < items.length; i += 1) {
    var it = items[i];
    if (!it.active) continue;
    if (category !== undefined && category !== '' && it.category !== category) continue;
    if (needle !== '' && it.name.toLowerCase().indexOf(needle) === -1) continue;
    var needs = it.currentQty <= it.reorderLevel;
    if (reorderOnly && !needs) continue;
    rows.push({
      id: it.id,
      name: it.name,
      category: it.category,
      unit: it.unit,
      currentQty: it.currentQty,
      reorderLevel: it.reorderLevel,
      location: it.location,
      statusColour: needs ? 'red' : 'green',
      statusText: needs ? 'Below reorder level' : 'OK',
      needsReorder: needs
    });
  }
  var key = filter.sortKey === undefined ? 'name' : filter.sortKey;
  var dir = filter.sortDir === 'desc' ? -1 : 1;
  rows.sort(function (a: ItemRow, b: ItemRow): number {
    var av: string | number;
    var bv: string | number;
    if (key === 'qty') {
      av = a.currentQty;
      bv = b.currentQty;
    } else if (key === 'category') {
      av = a.category;
      bv = b.category;
    } else {
      av = a.name;
      bv = b.name;
    }
    if (av < bv) return -1 * dir;
    if (av > bv) return 1 * dir;
    return 0;
  });
  return rows;
}

/**
 * Issues a quantity of an item: refuses when it exceeds stock (naming the shortfall),
 * otherwise writes an Issued movement and decrements current qty.
 * @param itemId - the item identifier
 * @param quantity - the positive integer quantity to issue
 * @param actor - the person issuing the item
 * @returns ok/error plus the written movement and updated item when successful
 */
function issueItem(itemId: string, quantity: number, actor: string): IssueResult {
  if (typeof itemId !== 'string' || itemId.trim() === '') {
    return { ok: false, error: 'itemId must be a non-empty string', movement: null, item: null };
  }
  if (!isNonNegativeInteger(quantity) || quantity <= 0) {
    return { ok: false, error: 'quantity must be a positive integer', movement: null, item: null };
  }
  var item = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, error: 'item not found: ' + itemId, movement: null, item: null };
  }
  if (quantity > item.currentQty) {
    var shortfall = quantity - item.currentQty;
    return { ok: false, error: 'insufficient stock for ' + item.name + ': shortfall ' + shortfall.toString(), movement: null, item: null };
  }
  var m = addMovement(item, -quantity, 'Issued', actor, '');
  return { ok: true, error: '', movement: m, item: item };
}

/**
 * Receives stock: increments qty, writes a Received movement and marks any
 * Open/Approved/Ordered purchase request for the item as Received.
 * @param itemId - the item identifier
 * @param quantity - the positive integer quantity received
 * @param actor - the person receiving the delivery
 * @returns ok/error plus movement, updated item and transitioned request
 */
function receiveStock(itemId: string, quantity: number, actor: string): ReceiveResult {
  if (typeof itemId !== 'string' || itemId.trim() === '') {
    return { ok: false, error: 'itemId must be a non-empty string', movement: null, item: null, request: null };
  }
  if (!isNonNegativeInteger(quantity) || quantity <= 0) {
    return { ok: false, error: 'quantity must be a positive integer', movement: null, item: null, request: null };
  }
  var item = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, error: 'item not found: ' + itemId, movement: null, item: null, request: null };
  }
  var m = addMovement(item, quantity, 'Received', actor, '');
  var transitioned: PurchaseRequest | null = null;
  var i = 0;
  for (i = 0; i < state.purchaseRequests.length; i += 1) {
    var pr = state.purchaseRequests[i];
    if (pr.item !== itemId) continue;
    if (pr.status === 'Open' || pr.status === 'Approved' || pr.status === 'Ordered') {
      pr.status = 'Received';
      if (transitioned === null) transitioned = pr;
    }
  }
  return { ok: true, error: '', movement: m, item: item, request: transitioned };
}

/**
 * Adjusts or damages an item: an Adjustment requires a non-empty note and may set
 * qty to a counted value (delta computed as counted minus current).
 * @param itemId - the item identifier
 * @param quantity - the counted quantity when reason is Adjustment, or the damage amount
 * @param reason - 'Damaged' or 'Adjustment'
 * @param actor - the person performing the operation
 * @param note - the note, required for an Adjustment
 * @returns ok/error plus the written movement and updated item
 */
function adjustStock(itemId: string, quantity: number, reason: string, actor: string, note: string): IssueResult {
  if (typeof itemId !== 'string' || itemId.trim() === '') {
    return { ok: false, error: 'itemId must be a non-empty string', movement: null, item: null };
  }
  if (reason !== 'Damaged' && reason !== 'Adjustment') {
    return { ok: false, error: 'reason must be Damaged or Adjustment', movement: null, item: null };
  }
  var item = findItem(state.items, itemId);
  if (item === null) {
    return { ok: false, error: 'item not found: ' + itemId, movement: null, item: null };
  }
  if (reason === 'Adjustment') {
    if (typeof note !== 'string' || note.trim() === '') {
      return { ok: false, error: 'a note is required for an Adjustment', movement: null, item: null };
    }
    if (!isNonNegativeInteger(quantity)) {
      return { ok: false, error: 'counted qty must be a non-negative integer', movement: null, item: null };
    }
    var delta = quantity - item.currentQty;
    var ma = addMovement(item, delta, 'Adjustment', actor, note);
    return { ok: true, error: '', movement: ma, item: item };
  }
  if (!isNonNegativeInteger(quantity) || quantity <= 0) {
    return { ok: false, error: 'quantity must be a positive integer', movement: null, item: null };
  }
  if (quantity > item.currentQty) {
    var shortfall = quantity - item.currentQty;
    return { ok: false, error: 'insufficient stock for ' + item.name + ': shortfall ' + shortfall.toString(), movement: null, item: null };
  }
  var md = addMovement(item, -quantity, 'Damaged', actor, note);
  return { ok: true, error: '', movement: md, item: item };
}

/**
 * Recomputes each item's qty from the movement log and reports mismatches
 * between the expected (movement-sum) and stored qty.
 * @param items - the item records to check
 * @param movements - the full movement log
 * @returns ok flag plus the list of items whose stored qty does not match
 */
function checkInvariant(items: Item[], movements: Movement[]): InvariantReport {
  var mismatches: InvariantMismatch[] = [];
  var i = 0;
  for (i = 0; i < items.length; i += 1) {
    var it = items[i];
    var expected = 0;
    var j = 0;
    for (j = 0; j < movements.length; j += 1) {
      if (movements[j].item === it.id) expected += movements[j].delta;
    }
    if (expected !== it.currentQty) {
      mismatches.push({ itemId: it.id, expected: expected, stored: it.currentQty });
    }
  }
  return { ok: mismatches.length === 0, mismatches: mismatches };
}

/**
 * Computes the dashboard: total items, count below reorder, count of open purchase
 * requests and total value on hand in integer pence (items without unit cost are zero).
 * @param items - the item records
 * @param purchaseRequests - the purchase request records
 * @returns the dashboard counters and total value in pence
 */
function dashboard(items: Item[], purchaseRequests: PurchaseRequest[]): Record<string, number> {
  var totalItems = items.length;
  var belowReorder = 0;
  var totalPence = 0;
  var i = 0;
  for (i = 0; i < items.length; i += 1) {
    var it = items[i];
    if (it.currentQty <= it.reorderLevel) belowReorder += 1;
    var cost = typeof it.unitCostPence === 'number' ? it.unitCostPence : 0;
    totalPence += it.currentQty * cost;
  }
  var openRequests = 0;
  var j = 0;
  for (j = 0; j < purchaseRequests.length; j += 1) {
    if (purchaseRequests[j].status === 'Open') openRequests += 1;
  }
  return {
    totalItems: totalItems,
    belowReorder: belowReorder,
    openRequests: openRequests,
    totalValuePence: totalPence
  };
}

/**
 * Generates an id for a domain record deterministically from a seed string.
 * @param seed - the seed used to derive the id
 * @returns a stable id string for the given seed
 */
function makeId(seed: string): string {
  var h = 0;
  var i = 0;
  for (i = 0; i < seed.length; i += 1) {
    h = (h * 31 + seed.charCodeAt(i)) % 2147483647;
  }
  return seed + '_' + h.toString();
}
export { listItems, issueItem, receiveStock, adjustStock, checkInvariant, dashboard, persistState, makeId };

